  "id": "idea-sh3-flaschenoeffner",
  "region": "cn",
  "idea": true,
  "name": "Sonne im Flaschenöffner 上海环球金融中心",
  "city": "Shanghai",
  "district": "Bund, Huangpu",
  "category": "Fotoidee",
  "address": "Bund, Huangpu",
  "lat": 31.2414,
  "lng": 121.4884,
  "approx": false,
  "when": "day",
  "note": "Das trapezförmige Loch in der Spitze des Shanghai World Financial Center (492 m) ist 46 m breit – aus 1,6 km Entfernung gerade dreimal so breit wie die Sonnenscheibe. Am Reisewochenende steht die Morgensonne vom nördlichen Bund aus für etwa zwei Minuten exakt im „Flaschenöffner“: ein gleißender Kern im dunklen Turm, wie ein Auge. Im typischen Shanghaier Morgendunst wird die Sonne orange und lässt sich ohne Überstrahlung abbilden.",
  "tip": "Rechnerischer Standpunkt: Bund-Promenade knapp nördlich des Chen-Yi-Platzes, gegenüber dem Peace Hotel (31.2413–31.2416 N), an allen drei Morgen (29./30./31.10.) gegen 07:33–07:34 Uhr, Sonnenhöhe 16°, Azimut 117–118°. 400–600 mm, Stativ, ND-Filter (ND 3.0) oder bei Dunst ohne; Belichtung auf die Sonnenkante, 1/1000 s f/11 ISO 100, Serie im 2-s-Intervall. Die Sonne wandert in ~1 min ihren Durchmesser – schon 10 Minuten vorher Position suchen und seitlich an der Brüstung justieren, bis die Turmachse mit dem Sonnenweg fluchtet. Nie ohne Filter durch den Sucher in die Sonne blicken (Live-View nutzen). ★★★",
