  "tip": "Gerechnet: Do 29.10. 07:18 Uhr, Fr 30.10. 07:19 Uhr, Sa 31.10. 07:20 Uhr; Sonnenhöhe 13,5°, Azimut 115–116°, Entfernung 2,6 km. Standpunkt Nordende der Brücke (an jedem Tag ~20–40 m weiter nordöstlich). 300–600 mm für die Spitze formatfüllend, oder 70–200 mm mit dem Kanal im Vordergrund; für den Stern f/16 und Sonne halb hinter der Turmkante verstecken. ND-Filter bei klarer Luft. Danach direkt weiter zum Bund (10 Min. zu Fuß) für den Flaschenöffner um 07:33 Uhr. ★★",
